import {fieldConfigs,renderField} from './field-model-view.js';
import {quantum3Configs,renderQuantum3} from './quantum3-model-view.js';
import {quantum2Configs,renderQuantum2} from './quantum2-model-view.js';
import {quantumConfigs,renderQuantum} from './quantum-model-view.js';
import {waveConfigs,renderWave} from './wave-model-view.js';
import {emConfigs,renderEM} from './em-model-view.js';
import {magnitude,constantVelocity,constantAcceleration,projectile,flightTime,acceleration,relativeUncertainty,unitCircle,squareFunction,complexValue,diagonalAction,radianGeometry} from './physics.js';
export const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(x,n=2)=>Number(x.toFixed(n)).toLocaleString('en-US');
const line=(x1,y1,x2,y2,color='#50735c',width=2,dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${width}" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
const txt=(x,y,t,color='#5b6c55',size=12,anchor='middle')=>`<text x="${x}" y="${y}" fill="${color}" font-size="${size}" font-family="system-ui,sans-serif" text-anchor="${anchor}">${esc(t)}</text>`;
const circle=(x,y,r=7,color='#24594d')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/>`;
const svg=(content,label)=>`<svg viewBox="0 0 420 230" role="img" aria-label="${esc(label)}">${content}</svg>`;
const readout=arr=>`<div class="model-readout">${arr.map(([a,b])=>`<div>${esc(a)}<b>${esc(b)}</b></div>`).join('')}</div>`;
const graph=(points,{xmin=0,xmax=10,ymin=-5,ymax=5,xlabel='Time (s)',ylabel='Position (m)',fill=false}={})=>{const X=x=>50+(x-xmin)/(xmax-xmin)*340,Y=y=>185-(y-ymin)/(ymax-ymin)*145;let s='';for(let i=0;i<=4;i++){const x=xmin+(xmax-xmin)*i/4,y=ymin+(ymax-ymin)*i/4;s+=line(X(x),40,X(x),185,'#dce4d2',1)+line(50,Y(y),390,Y(y),'#dce4d2',1)+txt(X(x),204,f(x,1),'#64725d',10)+txt(40,Y(y)+3,f(y,1),'#64725d',10,'end');}s+=txt(220,225,xlabel,'#4c6550',11)+txt(50,20,ylabel,'#4c6550',11,'start');if(ymin<=0&&ymax>=0)s+=line(50,Y(0),390,Y(0),'#8c9d81',1.5);const p=points.map(([x,y])=>`${X(x)},${Y(y)}`).join(' ');if(fill)s+=`<polygon points="${X(points[0][0])},${Y(0)} ${p} ${X(points.at(-1)[0])},${Y(0)}" fill="#d4b46a" opacity=".35"/>`;s+=`<polyline points="${p}" fill="none" stroke="#285d50" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`;return s;};
const configs={
 ...fieldConfigs, ...emConfigs, ...waveConfigs, ...quantumConfigs, ...quantum2Configs, ...quantum3Configs,
 radian:[['radius','Radius',1,4.5,.5,2,'cm'],['angle','Turn',0,6.28,.01,1,'rad']],
 trig:[['theta','Angle',0,360,15,60,'°']],derivative:[['point','Input x',0,4,.1,2,'']],integral:[['end','Upper endpoint',0,4,.1,3,'']],complex:[['real','Real component',-4,4,.5,2,''],['imaginary','Imaginary component',-4,4,.5,3,'']],matrix:[['x','Input x',-3,3,.5,1,''],['y','Input y',-3,3,.5,1,'']],
 units:[['length','Length',.1,3,.1,1.8,'m']],scale:[['exponent','Power of ten',-6,6,1,-3,'']],relationship:[['speed','Speed',.1,2,.1,.4,'m/s'],['time','Elapsed time',1,10,1,5,'s']],vector:[['x','East component',0,10,1,4,'m'],['y','North component',0,10,1,3,'m']],slope:[['v','Velocity',-3,3,.5,1,'m/s']],area:[['v','Velocity',-3,3,.5,2,'m/s'],['t','Duration',1,5,.5,3,'s']],uncertainty:[['u','Stated uncertainty',.1,3,.1,.5,'cm']],motion:[['x0','Initial position',-5,5,1,-3,'m'],['v','Velocity',-2,2,.5,2,'m/s'],['t','Elapsed time',0,5,.5,4,'s']],acceleration:[['v0','Initial velocity',-5,5,1,-4,'m/s'],['a','Acceleration',-3,3,.5,2,'m/s²'],['t','Elapsed time',0,4,.25,2,'s']],projectile:[['vx','Initial horizontal velocity',1,10,.5,5,'m/s'],['vy','Initial upward velocity',1,10,.5,6,'m/s']],force:[['right','Rightward force',0,15,1,10,'N'],['left','Leftward force',0,15,1,4,'N'],['mass','Mass',1,10,.5,3,'kg']]
};
function display(type,p,visual){
 const em=renderField(type,p,visual)??renderQuantum3(type,p,visual)??renderQuantum2(type,p,visual)??renderQuantum(type,p,visual)??renderWave(type,p,visual)??renderEM(type,p,visual);if(em!==null)return em+((visual.items??[]).length?`<p class="caption">Lesson summary—not live model readings</p><div class="concept-items">${visual.items.map(x=>`<div class="concept-item"><span>${esc(x.label)}</span><b>${esc(x.value)}</b></div>`).join('')}</div>`:'');
 if(type==='radian'){const q=radianGeometry(p.radius,p.angle),cx=210,cy=110,r=18*p.radius;const points=Array.from({length:81},(_,i)=>{const a=p.angle*i/80;return `${cx+r*Math.cos(a)},${cy-r*Math.sin(a)}`;}).join(' ');let s=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#cbd6bf" stroke-width="3"/>`+line(cx,cy,cx+r,cy,'#b88c35',4)+line(cx,cy,cx+r*Math.cos(p.angle),cy-r*Math.sin(p.angle),'#78936b',1.5,'4 4')+`<polyline points="${points}" fill="none" stroke="#22594f" stroke-width="5" stroke-linecap="round"/>`+circle(cx,cy,4,'#6c795e')+txt(cx-8,cy+19,'Centre',undefined,10,'end')+txt(cx,218,'Gold: radius · green: traced arc',undefined,11);return svg(s,`A circle of radius ${f(q.radius)} centimetres. A turn of ${f(q.angle)} radians traces a curved arc of ${f(q.arc)} centimetres. At one radian the arc and radius are equally long.`)+readout([['Radius r',f(q.radius)+' cm'],['Arc s',f(q.arc)+' cm'],['Turn θ',f(q.angle)+' rad']]);}

 if(type==='trig'){const u=unitCircle(p.theta),cx=210,cy=108,r=74;let s=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#c9d5be" stroke-width="2"/>`+line(110,cy,310,cy,'#9bab8a',1)+line(cx,15,cx,201,'#9bab8a',1)+line(cx,cy,cx+r*u.x,cy-r*u.y,'#285d50',3)+circle(cx+r*u.x,cy-r*u.y,6)+txt(325,cy+4,'x',undefined,11)+txt(cx+13,20,'y',undefined,11)+txt(cx,223,'Dimensionless unit circle',undefined,11);return svg(s,`Angle ${p.theta} degrees equals ${f(u.radians,3)} radians. Unit-circle coordinates x = ${f(u.x,3)}, y = ${f(u.y,3)}.`)+readout([['cos θ',f(u.x,3)],['sin θ',f(u.y,3)],['Radians',f(u.radians,3)]]);}
 if(type==='derivative'){const q=squareFunction(p.point),pts=Array.from({length:41},(_,i)=>[i/10,(i/10)**2]),x1=Math.max(p.point/2,p.point-.5),x2=Math.min(4,p.point+.5);let s=graph(pts,{xmax:4,ymin:0,ymax:16,xlabel:'Input x (dimensionless)',ylabel:'f(x) = x²'});s+=line(50+x1/4*340,185-(q.value+q.slope*(x1-p.point))/16*145,50+x2/4*340,185-(q.value+q.slope*(x2-p.point))/16*145,'#ba8c35',3)+circle(50+p.point/4*340,185-q.value/16*145,5,'#ba8c35');return svg(s,`Parabola f(x) = x squared with tangent at x ${f(p.point)}. Value ${f(q.value)}, local slope ${f(q.slope)}. Both axes are dimensionless.`)+readout([['Function value',f(q.value)],['Local slope',f(q.slope)]]);}
 if(type==='integral'){const q=squareFunction(p.end);return svg(graph([[0,0],[p.end,2*p.end]],{xmax:4,ymin:0,ymax:8,xlabel:'Input x (dimensionless)',ylabel:'f(x) = 2x',fill:true}),`The area under 2x from zero to ${f(p.end)} is ${f(q.integralOf2x)}. The graph is dimensionless.`)+readout([['Upper endpoint',f(p.end)],['Accumulated area',f(q.integralOf2x)]]);}
 if(type==='complex'){const q=complexValue(p.real,p.imaginary),cx=210,cy=110,k=18;let s=line(105,cy,315,cy,'#9bab8a',1)+line(cx,12,cx,202,'#9bab8a',1)+txt(337,cy+4,'Real',undefined,10)+txt(cx+13,17,'Imaginary',undefined,10,'start')+line(cx,cy,cx+k*q.real,cy-k*q.imaginary,'#285d50',3)+circle(cx+k*q.real,cy-k*q.imaginary,6)+line(cx,cy,cx+k*q.real,cy+k*q.imaginary,'#b28b3c',2,'5 4')+circle(cx+k*q.real,cy+k*q.imaginary,4,'#b28b3c')+txt(cx,225,'Solid: z · dashed: conjugate z*',undefined,11);return svg(s,`Complex number ${p.real} plus ${p.imaginary} i, magnitude squared ${f(q.squaredMagnitude)}. The dashed conjugate has the opposite imaginary component. Axes are dimensionless and equally scaled.`)+readout([['Magnitude |z|',f(q.magnitude,3)],['|z|²',f(q.squaredMagnitude)]]);}
 if(type==='matrix'){const out=diagonalAction(p.x,p.y),cx=210,cy=110,k=18;let s=line(85,cy,335,cy,'#9bab8a',1)+line(cx,20,cx,200,'#9bab8a',1)+txt(350,cy+4,'x',undefined,11)+txt(cx+12,23,'y',undefined,11)+line(cx,cy,cx+k*p.x,cy-k*p.y,'#285d50',4)+circle(cx+k*p.x,cy-k*p.y,5)+line(cx,cy,cx+k*out.x,cy-k*out.y,'#b28b3c',2)+circle(cx+k*out.x,cy-k*out.y,5,'#b28b3c')+txt(cx,225,'Green: input · gold: output',undefined,11);return svg(s,`Diagonal matrix with entries 2 and 1 maps input (${p.x}, ${p.y}) to (${out.x}, ${out.y}). Axes are dimensionless and equally scaled.`)+readout([['Input',`(${f(p.x)}, ${f(p.y)})`],['Output',`(${f(out.x)}, ${f(out.y)})`]]);}

 if(type==='units'){let s=line(45,130,375,130,'#9aa98a',3);for(let i=0;i<=10;i++)s+=line(45+i*33,120,45+i*33,140,'#8d9d7e',1)+txt(45+i*33,157,f(i*.3),undefined,10);s+=`<rect x="45" y="74" width="${p.length/3*330}" height="33" rx="6" fill="#295e50"/>`+txt(210,190,'Ruler scale (m)');return svg(s,`A length of ${f(p.length)} metres on a ruler marked zero to three metres.`)+readout([['Metres',f(p.length)+' m'],['Centimetres',f(p.length*100)+' cm']]);}
 if(type==='scale'){const n=3*10**p.exponent;return `<div class="model-output"><div class="big-number">3 × 10<sup>${p.exponent}</sup> m</div><div class="big-number" style="font-size:29px">${n.toLocaleString('en-US',{maximumFractionDigits:9})} m</div>${readout([['Exponent change','+1 → 10 times larger']])}</div>`;}
 if(type==='relationship'){return svg(graph([[0,0],[p.time,p.speed*p.time]],{xmax:10,ymin:0,ymax:20,xlabel:'Elapsed time (s)',ylabel:'Distance travelled (m)'}),`Distance rises at ${f(p.speed)} metres per second, reaching ${f(p.speed*p.time)} metres after ${f(p.time)} seconds.`)+readout([['Distance',f(p.speed*p.time)+' m']]);}
 if(type==='vector'){const x=65+p.x*27,y=190-p.y*14;let s=line(65,190,365,190,'#91a17d',1)+line(65,190,65,35,'#91a17d',1)+line(65,190,x,190,'#c49a46',3,'6 4')+line(x,190,x,y,'#c49a46',3,'6 4')+line(65,190,x,y,'#285d50',4)+circle(65,190,4)+circle(x,y,6)+txt(375,207,'East',undefined,10)+txt(65,22,'North',undefined,10)+txt(45,210,'Start',undefined,10)+txt(x+5,y-13,'Finish',undefined,10);return svg(s,`${p.x} metres east then ${p.y} metres north. Displacement magnitude ${f(magnitude(p.x,p.y))} metres; path length ${p.x+p.y} metres. Axes use different display scales.`)+readout([['Path length',f(p.x+p.y)+' m'],['Displacement',f(magnitude(p.x,p.y))+' m']])+`<p class="caption">Diagram axes have different display scales; use the component values, not the drawn angle.</p>`;}
 if(type==='slope'){return svg(graph([[0,0],[5,p.v*5]],{xmax:5,ymin:-15,ymax:15}),`Position changes from zero to ${f(p.v*5)} metres in five seconds with velocity ${f(p.v)} metres per second.`)+readout([['Slope = velocity',f(p.v)+' m/s']]);}
 if(type==='area'){return svg(graph([[0,p.v],[p.t,p.v]],{xmax:5,ymin:-3,ymax:3,ylabel:'Velocity (m/s)',fill:true}),`Constant velocity ${p.v} metres per second for ${p.t} seconds. Signed area ${f(p.v*p.t)} metres.`)+readout([['Displacement',f(p.v*p.t)+' m'],['Distance',f(Math.abs(p.v*p.t))+' m']]);}
 if(type==='uncertainty'){const lo=210-p.u*40,hi=210+p.u*40;let s=line(50,155,370,155,'#8d9e7f',2);for(let i=16;i<=24;i++)s+=line(50+(i-16)*40,150,50+(i-16)*40,161,'#8d9e7f',1)+txt(50+(i-16)*40,179,i,undefined,10);s+=`<rect x="${lo}" y="80" width="${hi-lo}" height="46" rx="6" fill="#e1c780"/>`+line(210,65,210,143,'#285d50',3)+txt(210,211,'Length (cm)');return svg(s,`Estimate 20 centimetres with stated uncertainty plus or minus ${p.u} centimetres, from ${f(20-p.u)} to ${f(20+p.u)} centimetres.`)+readout([['Estimate','20 ± '+f(p.u)+' cm'],['Relative uncertainty',f(relativeUncertainty(20,p.u)*100)+'%']]);}
 if(type==='motion'){const end=constantVelocity(p.x0,p.v,p.t);return svg(graph([[0,p.x0],[p.t,end]],{xmax:5,ymin:-15,ymax:15}),`Initial position ${p.x0} metres, velocity ${p.v} metres per second, elapsed time ${p.t} seconds, final position ${f(end)} metres.`)+readout([['Displacement',f(p.v*p.t)+' m'],['Final position',f(end)+' m']]);}
 if(type==='acceleration'){const out=constantAcceleration(0,p.v0,p.a,p.t);return svg(graph([[0,p.v0],[p.t,out.v]],{xmax:4,ymin:-18,ymax:18,ylabel:'Velocity (m/s)'}),`Velocity changes from ${p.v0} to ${f(out.v)} metres per second over ${p.t} seconds at constant acceleration ${p.a} metres per second squared.`)+readout([['Velocity',f(out.v)+' m/s'],['Displacement',f(out.x)+' m']]);}
 if(type==='projectile'){const T=flightTime(p.vy),R=p.vx*T,H=p.vy*p.vy/(2*9.81);const pts=Array.from({length:41},(_,i)=>{const a=projectile(p.vx,p.vy,T*i/40);return [a.x,Math.max(0,a.y)];});let s=graph(pts,{xmax:21,ymin:0,ymax:6,xlabel:'Horizontal position (m)',ylabel:'Height (m)'});for(let i=0;i<=8;i++){const a=projectile(p.vx,p.vy,T*i/8);s+=circle(50+a.x/21*340,185-Math.max(0,a.y)/6*145,3,'#aa8132');}return svg(s,`Ideal projectile launched at ${p.vx} metres per second horizontally and ${p.vy} metres per second upward. Flight time ${f(T)} seconds, range ${f(R)} metres, maximum height ${f(H)} metres.`)+readout([['Flight time',f(T)+' s'],['Range',f(R)+' m'],['Max height',f(H)+' m']]);}
 if(type==='force'){const a=acceleration(p.right,p.left,p.mass);let s=`<rect x="170" y="80" width="80" height="70" rx="9" fill="#dbe4d0" stroke="#63845f"/>`+txt(210,122,f(p.mass)+' kg','#284d3e',16);if(p.right>0)s+=line(250,115,250+p.right*8,115,'#285d50',5)+`<path d="M${250+p.right*8-10} 107l10 8-10 8" fill="none" stroke="#285d50" stroke-width="3"/>`;if(p.left>0)s+=line(170,115,170-p.left*8,115,'#b58b3b',5)+`<path d="M${170-p.left*8+10} 107l-10 8 10 8" fill="none" stroke="#b58b3b" stroke-width="3"/>`;s+=txt(310,83,f(p.right)+' N','#285d50')+txt(100,83,f(p.left)+' N','#8d6726')+txt(210,193,'Positive direction →');return svg(s,`${p.right} newtons rightward and ${p.left} newtons leftward on ${p.mass} kilograms. Net force ${f(p.right-p.left)} newtons; acceleration ${f(a)} metres per second squared.`)+readout([['Net force',f(p.right-p.left)+' N'],['Acceleration',f(a)+' m/s²']]);}
 return `<div class="concept-items">${(visual.items??[]).map(x=>`<div class="concept-item"><span>${esc(x.label)}</span><b>${esc(x.value)}</b></div>`).join('')}</div>`;
}
export const hasInteractiveModel = visual => Boolean(configs[visual?.type]?.length);
export function mountModel(container,visual){const type=visual.type,cs=configs[type]??[],p=Object.fromEntries(cs.map(c=>[c[0],c[5]]));container.innerHTML=`<div class="visual-label"><span>${cs.length?'INTERACTIVE MODEL':'VISUAL SUMMARY'}</span><span aria-hidden="true">✦</span></div><h3>${esc(visual.title)}</h3><div class="model-stage" id="modelStage"></div><div class="controls">${cs.map(([id,label,min,max,step,value,unit])=>`<div class="control"><label for="ctrl-${id}">${esc(label)}<output id="out-${id}" for="ctrl-${id}">${esc(f(value)+' '+unit)}</output></label><input type="range" id="ctrl-${id}" min="${min}" max="${max}" step="${step}" value="${value}" aria-valuetext="${esc(f(value)+' '+unit)}"></div>`).join('')}</div>${cs.length?'<button class="model-reset" type="button">Reset model</button>':''}<p class="caption">${esc(visual.caption)}</p>`;const render=()=>container.querySelector('.model-stage').innerHTML=display(type,p,visual);for(const [id,label,min,max,step,value,unit]of cs){const input=container.querySelector('#ctrl-'+id);input.addEventListener('input',()=>{p[id]=Number(input.value);container.querySelector('#out-'+id).textContent=f(p[id])+' '+unit;input.setAttribute('aria-valuetext',f(p[id])+' '+unit);render();});}container.querySelector('.model-reset')?.addEventListener('click',()=>{for(const c of cs){p[c[0]]=c[5];const input=container.querySelector('#ctrl-'+c[0]);input.value=c[5];input.dispatchEvent(new Event('input'));}});render();}
